import json
import time
import uuid
from pathlib import Path

from observability import Recorder, failure_class, queue_context


class ProviderError(Exception):
    def __init__(self, code, detail):
        super().__init__(detail)
        self.code = code


class Runner:
    def __init__(self, queue_dir, provider):
        self.queue_dir = Path(queue_dir)
        self.queue_dir.mkdir(parents=True, exist_ok=True)
        self.provider = provider
        self._observability = Recorder(self.queue_dir)

    def _enqueue(self, job, entry_point="unknown"):
        run_id = uuid.uuid4().hex
        message = {
            "run_id": run_id, "job": job,
            "_observability": {"entry_point": entry_point, "queued_at": time.time()},
        }
        try:
            (self.queue_dir / (run_id + ".json")).write_text(json.dumps(message))
        except BaseException as error:
            self._observability.record(
                "enqueue_failed", run_id=run_id, entry_point=entry_point, phase="enqueue",
                outcome="cancelled" if failure_class(error) == "cancelled" else "exception",
                failure=failure_class(error),
            )
            raise
        self._observability.record(
            "queue_enqueued", run_id=run_id, entry_point=entry_point,
            phase="enqueue", outcome="accepted",
        )
        return run_id

    def scheduled(self, job):
        return self._enqueue(job, "scheduled")

    def manual(self, job):
        return self._enqueue(job, "manual")

    def execute(self, run_id):
        started = time.perf_counter()
        execution_id = uuid.uuid4().hex
        entry_point, queue_wait = "unknown", None
        provider_duration = None
        phase = "queue_read"
        try:
            path = self.queue_dir / (run_id + ".json")
            message = json.loads(path.read_text())
            job = message["job"]
            entry_point, queue_wait = queue_context(message, time.time())
            self._observability.record(
                "execution_started", run_id=run_id, execution_id=execution_id,
                entry_point=entry_point, phase="provider", outcome="started",
                queue_wait_seconds=queue_wait,
            )
            phase = "provider"
            provider_started = time.perf_counter()
            try:
                receipt = self.provider.send(job)
            except ProviderError as error:
                result = {"run_id": run_id, "ok": False, "code": error.code}
                outcome = "provider_error"
                failure = "timeout" if isinstance(error.code, str) and error.code == "TIMEOUT" else "provider_error"
            else:
                result = {"run_id": run_id, "ok": True, "receipt": receipt}
                outcome, failure = "success", "none"
            finally:
                provider_duration = time.perf_counter() - provider_started
            phase = "queue_remove"
            path.unlink()
        except BaseException as error:
            self._observability.record(
                "execution_finished", run_id=run_id, execution_id=execution_id,
                entry_point=entry_point, phase=phase,
                outcome="cancelled" if failure_class(error) == "cancelled" else "exception",
                failure=failure_class(error), duration_seconds=time.perf_counter() - started,
                provider_duration_seconds=provider_duration, queue_wait_seconds=queue_wait,
            )
            raise
        self._observability.record(
            "execution_finished", run_id=run_id, execution_id=execution_id,
            entry_point=entry_point, phase="finished", outcome=outcome, failure=failure,
            duration_seconds=time.perf_counter() - started,
            provider_duration_seconds=provider_duration, queue_wait_seconds=queue_wait,
        )
        return result

