"""Local, best-effort operational events and bounded-window metrics."""

import argparse
from contextlib import closing
import json
import math
import os
from pathlib import Path
import re
import sqlite3
import sys
import time


RETENTION_SECONDS = 7 * 24 * 60 * 60
MAX_EVENTS = 10_000
BUSY_TIMEOUT_SECONDS = 0.025
ENTRY_POINTS = ("scheduled", "manual", "unknown")
OUTCOMES = ("success", "provider_error", "exception", "cancelled")
BUCKETS_SECONDS = (0.001, 0.005, 0.01, 0.05, 0.1, 0.5, 1, 5, 30)
EVENTS = {"queue_enqueued", "enqueue_failed", "execution_started", "execution_finished"}
PHASES = {"enqueue", "queue_read", "provider", "queue_remove", "finished"}
FAILURE_CLASSES = {"none", "timeout", "provider_error", "connection", "io", "invalid_queue", "unexpected", "cancelled"}
SCHEMA = """
CREATE TABLE IF NOT EXISTS events (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    recorded_at REAL NOT NULL,
    event TEXT NOT NULL,
    run_id TEXT,
    execution_id TEXT,
    entry_point TEXT NOT NULL,
    phase TEXT NOT NULL,
    outcome TEXT NOT NULL,
    failure_class TEXT NOT NULL,
    duration_seconds REAL,
    provider_duration_seconds REAL,
    queue_wait_seconds REAL,
    dropped_before INTEGER NOT NULL
)
"""


def store_path(queue_dir):
    return Path(queue_dir) / ".observability" / "events.sqlite3"


def safe_id(value):
    if isinstance(value, str) and len(value) == 32 and re.fullmatch("[0-9a-f]{32}", value):
        return value
    return None


def seconds(value):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return None
    if 0 <= value <= 1_000_000_000_000 and math.isfinite(value):
        return float(value)
    return None


def queue_context(message, now):
    metadata = message.get("_observability", {}) if isinstance(message, dict) else {}
    if not isinstance(metadata, dict):
        return "unknown", None
    entry_point = metadata.get("entry_point")
    if entry_point not in ENTRY_POINTS:
        entry_point = "unknown"
    queued_at = seconds(metadata.get("queued_at"))
    wait = now - queued_at if queued_at is not None and queued_at <= now else None
    return entry_point, wait


def failure_class(error):
    if isinstance(error, (KeyboardInterrupt, SystemExit)):
        return "cancelled"
    if isinstance(error, TimeoutError):
        return "timeout"
    if isinstance(error, ConnectionError):
        return "connection"
    if isinstance(error, OSError):
        return "io"
    if isinstance(error, json.JSONDecodeError):
        return "invalid_queue"
    return "unexpected"


class Recorder:
    def __init__(self, queue_dir):
        self.path = store_path(queue_dir)
        self.enabled = os.environ.get("BATCH_SENDER_OBSERVABILITY", "1") != "0"
        self.dropped = 0
        self.warned = False

    def record(self, event, *, run_id, execution_id=None, entry_point="unknown",
               phase, outcome, failure="none", duration_seconds=None,
               provider_duration_seconds=None, queue_wait_seconds=None):
        if not self.enabled:
            return
        try:
            row = (
                time.time(), event if event in EVENTS else "execution_finished",
                safe_id(run_id), safe_id(execution_id),
                entry_point if entry_point in ENTRY_POINTS else "unknown",
                phase if phase in PHASES else "finished",
                outcome if outcome in (*OUTCOMES, "accepted", "started") else "exception",
                failure if failure in FAILURE_CLASSES else "unexpected",
                seconds(duration_seconds), seconds(provider_duration_seconds),
                seconds(queue_wait_seconds), self.dropped,
            )
            self._write(row)
            self.dropped = 0
        except Exception:
            # Diagnostics must not replace the operation's result or exception.
            self.dropped = min(self.dropped + 1, 2**63 - 1)
            if not self.warned:
                self.warned = True
                try:
                    sys.stderr.write("batch_sender.observability_unavailable: local events may be missing\n")
                except Exception:
                    pass

    def _write(self, row):
        self.path.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
        try:
            descriptor = os.open(self.path, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o600)
        except FileExistsError:
            pass
        else:
            os.close(descriptor)
        with closing(sqlite3.connect(self.path, timeout=BUSY_TIMEOUT_SECONDS)) as connection:
            connection.execute("PRAGMA max_page_count = 4096")
            with connection:
                connection.execute(SCHEMA)
                connection.execute(
                    "INSERT INTO events (recorded_at, event, run_id, execution_id, entry_point, "
                    "phase, outcome, failure_class, duration_seconds, provider_duration_seconds, "
                    "queue_wait_seconds, dropped_before) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                    row,
                )
                connection.execute(
                    "DELETE FROM events WHERE recorded_at < ? OR id <= "
                    "(SELECT COALESCE(MAX(id), 0) - ? FROM events)",
                    (row[0] - RETENTION_SECONDS, MAX_EVENTS),
                )


def read_events(queue_dir, now):
    database = store_path(queue_dir)
    try:
        if not database.is_file():
            return None, "store_missing"
        with closing(sqlite3.connect(database.resolve().as_uri() + "?mode=ro", uri=True,
                                     timeout=BUSY_TIMEOUT_SECONDS)) as connection:
            connection.row_factory = sqlite3.Row
            rows = connection.execute(
                "SELECT * FROM events WHERE recorded_at >= ? AND recorded_at <= ? "
                "ORDER BY id DESC LIMIT ?", (now - RETENTION_SECONDS, now, MAX_EVENTS)
            ).fetchall()
            return [dict(row) for row in reversed(rows)], None
    except (OSError, sqlite3.Error):
        return None, "store_unreadable"


def histogram(values):
    return {
        "unit": "seconds", "count": len(values), "sum": sum(values),
        "cumulative_buckets": [
            {"le": bound, "count": sum(value <= bound for value in values)}
            for bound in BUCKETS_SECONDS
        ] + [{"le": "+Inf", "count": len(values)}],
    }


def metrics(events):
    enqueued = {entry: 0 for entry in ENTRY_POINTS}
    enqueue_failures = dict(enqueued)
    attempts = dict(enqueued)
    completions = {entry: {outcome: 0 for outcome in OUTCOMES} for entry in ENTRY_POINTS}
    durations, provider_durations, waits = [], [], []
    unknown_waits = 0
    for event in events:
        entry = event["entry_point"]
        if event["event"] == "queue_enqueued":
            enqueued[entry] += 1
        elif event["event"] == "enqueue_failed":
            enqueue_failures[entry] += 1
        elif event["event"] == "execution_started":
            attempts[entry] += 1
            if event["queue_wait_seconds"] is None:
                unknown_waits += 1
            else:
                waits.append(event["queue_wait_seconds"])
        elif event["event"] == "execution_finished":
            completions[entry][event["outcome"]] += 1
            if event["duration_seconds"] is not None:
                durations.append(event["duration_seconds"])
            if event["provider_duration_seconds"] is not None:
                provider_durations.append(event["provider_duration_seconds"])
    return {
        "enqueue_count": enqueued,
        "enqueue_failure_count": enqueue_failures,
        "provider_attempt_count": attempts,
        "execution_finished_count": completions,
        "execution_duration_seconds": histogram(durations),
        "provider_duration_seconds": histogram(provider_durations),
        "queue_wait_seconds": histogram(waits),
        "queue_wait_unknown_count": unknown_waits,
    }


def inspect_store(queue_dir, view="metrics", limit=20):
    now = time.time()
    events, error = read_events(queue_dir, now)
    result = {
        "available": error is None,
        "store": str(store_path(queue_dir)),
        "window_start": now - RETENTION_SECONDS,
        "window_end": now,
        "event_capacity": MAX_EVENTS,
        "completeness": "best_effort; missing events are unknown",
    }
    if error:
        return {**result, "reason": error}
    result.update({
        "retained_event_count": len(events),
        "oldest_event_at": events[0]["recorded_at"] if events else None,
        "newest_event_at": events[-1]["recorded_at"] if events else None,
        "known_dropped_event_count": sum(event["dropped_before"] for event in events),
    })
    if view == "events":
        result["events"] = events[-limit:]
    elif view == "status":
        latest = {}
        # A producer can commit its enqueue event after a consumer has finished.
        status_order = lambda item: (item["event"].startswith("execution_"), item["recorded_at"], item["id"])
        for event in events:
            if event["run_id"] is not None:
                previous = latest.get(event["run_id"])
                if previous is None or status_order(event) > status_order(previous):
                    latest[event["run_id"]] = event
        result["process_liveness"] = "unknown"
        result["runs"] = [
            {"run_id": event["run_id"], "execution_id": event["execution_id"],
             "entry_point": event["entry_point"], "last_observed_event": event["event"],
             "outcome": event["outcome"], "phase": event["phase"],
             "failure_class": event["failure_class"], "observed_at": event["recorded_at"],
             "age_seconds": max(0, now - event["recorded_at"])}
            for event in sorted(latest.values(), key=lambda item: item["id"], reverse=True)[:limit]
        ]
    else:
        result["metrics"] = metrics(events)
    return result


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--queue", required=True, type=Path)
    parser.add_argument("view", choices=("events", "metrics", "status"))
    parser.add_argument("--limit", type=int, default=20)
    args = parser.parse_args()
    if not 1 <= args.limit <= 1000:
        parser.error("--limit must be between 1 and 1000")
    result = inspect_store(args.queue, args.view, args.limit)
    print(json.dumps(result, indent=2, allow_nan=False))
    return 0 if result["available"] else 1


if __name__ == "__main__":
    raise SystemExit(main())

